async function observe(t,source,format,{screenshot=false}={}) {
 const dir=fs.mkdtempSync(path.join(os.tmpdir(),'archify-peer-svg-test-'));
 t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));
 const artifactPath=path.join(dir,'fixture.svg'),screenshotPath=screenshot?path.join(dir,'capture.png'):undefined;
 fs.writeFileSync(artifactPath,source);
 const {observePeerArtifact}=await import(modulePath);
 const result=await observePeerArtifact({artifactPath,format,chromePath,screenshotPath});
 assert.equal(fs.existsSync(result.observation.browserProfile),false,'private browser profile cleaned');
 if(screenshotPath)assert.ok(fs.statSync(screenshotPath).size>1000);
 return result;
}
const relations=r=>r.graph.edges.map(e=>[r.graph.nodes.find(n=>n.id===e.from)?.label,r.graph.nodes.find(n=>n.id===e.to)?.label,e.label]);
for(const format of ['drawio','excalidraw']) {
 const fixture=format==='drawio'?drawio:excalidraw;
 test(format+' frozen native paint establishes directed topology and measured geometry',{skip:!chromePath},async t=>{
  const r=await observe(t,fixture,format,{screenshot:true});
  assert.equal(r.graph.status,'verified',JSON.stringify(r.graph.unknownReasons));
  assert.deepEqual(r.graph.nodes.map(n=>n.label),['Source','Target']);
  assert.deepEqual(relations(r),[['Source','Target','']]);
  assert.deepEqual(r.observation.bounds,{x:80,y:90,width:1280,height:720});
  assert.equal(evaluateGeometry(r.observation).status,'verified');
 });
 test(format+' observes changed visible wording and ignores hidden metadata',{skip:!chromePath},async t=>{
  const source=fixture.replaceAll('Source','Intake Ω').replaceAll('Target','Queue β').replace('</svg>','<metadata>{"nodes":["Wrong"],"edges":[["Queue β","Intake Ω"]]}</metadata><g display="none"><rect width="100" height="40"/><text>Invented</text></g></svg>');
  const r=await observe(t,source,format);
  assert.equal(r.graph.status,'verified',JSON.stringify(r.graph.unknownReasons));
  assert.deepEqual(relations(r),[['Intake Ω','Queue β','']]);
 });
 test(format+' clipped native paint stays unverified',{skip:!chromePath},async t=>{
  const source=fixture.replace('<g ', '<g style="clip-path:inset(20%)" ');
  const r=await observe(t,source,format);assert.equal(r.graph.status,'unverified');
  assert.match(r.graph.unknownReasons.join(' '),/clip/i);
 });
}
test('drawio native branch and return edges bind actual visible labels',{skip:!chromePath},async t=>{
 const r=await observe(t,branch,'drawio');
 assert.equal(r.graph.status,'verified',JSON.stringify(r.graph.unknownReasons));
 assert.equal(r.graph.nodes.length,6);assert.equal(r.graph.edges.length,6);
 assert.ok(relations(r).some(e=>e[0]==='Fixture 6' && e[1]==='Fixture 2'));
 assert.ok(r.graph.edges.every(e=>e.label==='')); // Native fixture has no edge labels.
});
test('drawio reversed triangle paint cannot borrow claimed direction',{skip:!chromePath},async t=>{
 const source=drawio.replace('M 278.88 50 L 271.88 53.5 L 271.88 46.5 Z','M 271.88 50 L 278.88 53.5 L 278.88 46.5 Z');
 const r=await observe(t,source,'drawio');assert.equal(r.graph.status,'unverified');assert.match(r.graph.unknownReasons.join(' '),/arrow|direction/i);
});
test('excalidraw arrow wings hidden cannot establish an edge from source metadata',{skip:!chromePath},async t=>{
 const source=excalidraw.replaceAll('<path d="M125.','<path display="none" d="M125.');
 const r=await observe(t,source,'excalidraw');assert.equal(r.graph.status,'unverified');assert.equal(r.graph.edges.length,0);
});

