test('excalidraw native labeled branch and return establish visible directions',{skip:!chromePath},async t=>{
 const r=await observe(t,excalidrawBranch,'excalidraw');
 assert.equal(r.graph.status,'verified',JSON.stringify(r.graph.unknownReasons));
 assert.deepEqual(relations(r),[['Source','Decide','request'],['Decide','Accept','yes'],['Decide','Retry','no'],['Retry','Source','retry']]);
});
test('excalidraw reversed native open arrow paint changes actual direction',{skip:!chromePath},async t=>{
 // Mirror only arrow paint around its center; node labels remain unchanged.
 const source=excalidraw.replace('<g stroke-linecap="round"><g transform=', '<g stroke-linecap="round" transform="translate(590 0) scale(-1 1)"><g transform=');
 const r=await observe(t,source,'excalidraw');
 assert.equal(r.graph.status,'verified',JSON.stringify(r.graph.unknownReasons));
 assert.deepEqual(relations(r),[['Target','Source','']]);
});
for(const format of ['drawio','excalidraw'])test(format+' later opaque fill removes occluded label credit',{skip:!chromePath},async t=>{
 const fixture=format==='drawio'?drawio:excalidraw;
 const overlay=format==='drawio'?'<rect x="25" y="35" width="110" height="30" fill="white" pointer-events="none"/>':'<rect x="30" y="40" width="180" height="55" fill="white" pointer-events="none"/>';
 const r=await observe(t,fixture.replace('</svg>',overlay+'</svg>'),format);
 assert.equal(r.graph.status,'unverified');assert.ok(!r.graph.nodes.some(n=>n.label==='Source'));assert.match(r.graph.unknownReasons.join(' '),/cover/i);
});

test('excalidraw coincident arrow wings remain ambiguous',{skip:!chromePath},async t=>{
 const paths=[...excalidraw.matchAll(/<path d="([^"]+)"[^>]*><\/path>/g)];
 const source=excalidraw.replace(paths.at(-1)[0],paths.at(-2)[0]);
 const r=await observe(t,source,'excalidraw');
 assert.equal(r.graph.status,'unverified');assert.equal(r.graph.edges.length,0);
});

test('native route cannot use a hidden text label to authorize a masking rectangle',{skip:!chromePath},async t=>{
 const source=excalidrawBranch.replace('>request</text>',' style="display:none">request</text>');
 const r=await observe(t,source,'excalidraw');
 assert.equal(r.graph.status,'unverified');assert.match(r.graph.unknownReasons.join(' '),/mask/i);
});

