test('drawio native label backplates do not become spurious graph nodes',{skip:!chromePath},async t=>{
 const r=await observe(t,labeledDrawio,'drawio');
 assert.equal(r.graph.status,'verified',JSON.stringify(r.graph.unknownReasons));
 assert.equal(r.graph.nodes.length,6);assert.equal(r.graph.edges.length,6);
 assert.deepEqual(r.graph.edges.map(e=>e.label),['Route 1','Route 2','Route 3','Route 4','Route 5','Route 6']);
});

