test('native measured dangling endpoint is a known missing relation, not unknown evidence',{skip:!chromePath},async t=>{
 const r=await observe(t,danglingNative,'excalidraw');assert.equal(r.graph.status,'verified',JSON.stringify(r.graph.unknownReasons));
 assert.equal(r.graph.nodes.length,2);assert.equal(r.graph.edges.length,0);assert.equal(r.observation.edges.length,1);assert.equal(r.observation.edges[0].visible,false);assert.equal(r.observation.edges[0].to,null);
});
test('native nearby competing boxes keep endpoint association unverified',{skip:!chromePath},async t=>{
 // Two visible native rectangles bracket the tip with equally near borders.
 const target=classicDrawio.match(/<g data-cell-id="3">[\s\S]*?(?=<g data-cell-id="4">)/)[0];
 const copy=target.replace('data-cell-id="3"','data-cell-id="ignored-copy"').replace('>Target<','>Other<');
 const source=classicDrawio.replace('<g data-cell-id="4">','<g transform="translate(0 78)">'+copy+'</g><g data-cell-id="4">')
  .replace('M 140 50 L 273.63 50','M 140 50 L 200 50 L 200 89 L 273.63 89')
  .replace('d="M 278.88 50','transform="translate(0 39)" d="M 278.88 50');
 const r=await observe(t,source,'drawio');assert.equal(r.graph.status,'unverified');assert.match(r.graph.unknownReasons.join(' '),/ambiguous/i);
});
